def transform(grid):
    """
    Transform the grid:
    1. 1s stay unchanged (boundary)
    2. 0s outside the boundary become 2s (flood fill from edges)
    3. Interior 0s become 3s, except center stays 0
    4. Last row and last column stay 0
    """
    H, W = len(grid), len(grid[0])
    out = [[0]*W for _ in range(H)]

    # Copy 1s to output
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1:
                out[r][c] = 1

    # Do flood-fill to find "outside" 0s
    # Outside 0s are those connected to the grid boundary (but not inside the 1s)
    visited = [[False]*W for _ in range(H)]
    stack = []

    # Add all boundary cells that are 0 to the stack
    for r in range(H):
        if grid[r][0] == 0 and not visited[r][0]:
            stack.append((r, 0))
            visited[r][0] = True
        if grid[r][W-1] == 0 and not visited[r][W-1]:
            stack.append((r, W-1))
            visited[r][W-1] = True
    for c in range(W):
        if grid[0][c] == 0 and not visited[0][c]:
            stack.append((0, c))
            visited[0][c] = True
        if grid[H-1][c] == 0 and not visited[H-1][c]:
            stack.append((H-1, c))
            visited[H-1][c] = True

    # Flood fill
    while stack:
        r, c = stack.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if not visited[nr][nc] and grid[nr][nc] == 0:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    # Mark outside 0s as 2 (except last row and last col which stay 0)
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0:
                # Already preserved (last row/col) or inside
                if not visited[r][c] and r < H - 1 and c < W - 1:
                    out[r][c] = 2  # Outside

                # Inside becomes 3 (with center exception)
                elif visited[r][c] and r < H - 1 and c < W - 1:
                    # Interior 0 - check if center
                    out[r][c] = 3
                    # Center of the interior 3x3 is... hmm, need to determine

    return out


