def transform_debug(grid):
    H, W = len(grid), len(grid[0])
    out = [[0]*W for _ in range(H)]

    # Don't transform last row and last column
    valid_rows = range(H - 1)
    valid_cols = range(W - 1)

    # Copy 1s
    for r in valid_rows:
        for c in valid_cols:
            if grid[r][c] == 1:
                out[r][c] = 1

    # Flood fill to find "outside" 0s
    visited = [[False]*W for _ in range(H)]
    stack = []

    # Add all boundary cells that are 0
    for r in valid_rows:
        if grid[r][0] == 0:
            stack.append((r, 0))
            visited[r][0] = True
        if grid[r][W-1] == 0:
            stack.append((r, W-1))
            visited[r][W-1] = True
    for c in valid_cols:
        if grid[0][c] == 0:
            stack.append((0, c))
            visited[0][c] = True
        if grid[H-1][c] == 0:
            stack.append((H-1, c))
            visited[H-1][c] = True

    # List all visited cells
    print("Visited (outside):")
    for r in range(H):
        row_str = ""
        for c in range(W):
            if visited[r][c]:
                row_str += "o "
            else:
                row_str += "." if grid[r][c] == 0 else "#"
        print(row_str)

    # Flood fill
    while stack:
        r, c = stack.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if not visited[nr][nc] and grid[nr][nc] == 0:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    # Now fill
    for r in valid_rows:
        for c in valid_cols:
            if grid[r][c] == 1:
                out[r][c] = 1
            elif visited[r][c]:
                out[r][c] = 2  # Outside
            else:
                out[r][c] = 3  # Inside

    return out

